-- Generated from the readable, source-bound editorial models.
local _,ns=...
ns.AthenaQuestContextData={[15]={["opening"]="Kobold workers had made camp near the Echo Ridge Mine, a larger infestation than Marshal McBride’s scouts had expected.",["atomIDs"]={"15:description:1-80","15:description:83-157"},["sourceHash"]="1df8e6166fda022ef00b9cc823dc4a47d3f72f71d24024dc63e1760ab411f3d7",["review"]="SOURCE_BOUND_EDITORIAL_PARAPHRASE"},[18]={["opening"]="Thieves calling themselves the Defias Brotherhood had appeared around Northshire, across the river to the east.",["atomIDs"]={"18:description:1-68","18:description:71-163"},["sourceHash"]="4cae7b1cb49f042d0b3205d8e472da991589c6be01d1967b2ed7d49e6df212ba",["review"]="SOURCE_BOUND_EDITORIAL_PARAPHRASE"},[21]={["opening"]="The kobolds’ foothold in the mine threatened to grow stronger the longer they remained. Marshal McBride wanted them cleared from Northshire.",["atomIDs"]={"21:description:1-78","21:description:81-128","21:description:153-254"},["sourceHash"]="3cdd14a1eb633382f6c90249a3dba2c08de418e6722e17b41f0b7ce4a9ffdd84",["review"]="SOURCE_BOUND_EDITORIAL_PARAPHRASE"},[1598]={["opening"]="A novice from the Abbey had joined the Defias Brotherhood and stolen important books. Among them was the Powers of the Void, a volume Drusilla La Salle wanted for herself.",["atomIDs"]={"1598:description:218-301","1598:description:318-353","1598:description:358-438"},["sourceHash"]="a07d203956747c9ebb21a8a732d9708ba20bbbe0eada41a3b894dc69f44e66bc",["review"]="SOURCE_BOUND_EDITORIAL_PARAPHRASE"},[62]={["opening"]="Marshal Dughan had reports of another kobold haven, this time in the Fargodeep Mine. The trouble in Northshire might extend farther into Elwynn; the reports still needed to be checked.",["atomIDs"]={"62:description:1-56","62:description:59-143","62:description:148-209"},["sourceHash"]="acd6a95e133060a31ee6d1dfbee2bfb2469c885e4a90985eb4b002134e09147b",["review"]="SOURCE_BOUND_EDITORIAL_PARAPHRASE"},[76]={["opening"]="The more distant Jasperlode Mine also needed a scout. Marshal Dughan wanted to know whether kobolds had taken hold there.",["atomIDs"]={"76:description:69-136","76:description:141-191"},["sourceHash"]="9beedb05ea0ea386df1d29e8c5f972c2082a0f552ad2afedc4ee730c4bbb5d52",["review"]="SOURCE_BOUND_EDITORIAL_PARAPHRASE"},[65]={["opening"]="The Defias Brotherhood had driven Westfall’s people from their land. Gryan Stoutmantle needed to uncover the gang’s leader and hiding place; Wiley, a rogue in Lakeshire, owed him a favor.",["pending"]="{actor} took up the search, with Wiley as the first lead.",["result"]="{actor} followed Stoutmantle’s lead to Wiley in Lakeshire.",["atomIDs"]={"65:description:1-126","65:description:129-172","65:description:175-244","65:description:247-330"},["sourceHash"]="cdb487bd417d2bc3a0619df16e974a5c1c33850d18c326eb5240652e4af30447",["review"]="SOURCE_BOUND_EDITORIAL_PARAPHRASE",["baseOverrideRevision"]=1,["baseOverrideSetup"]="Gryan Stoutmantle sought the identity and hiding place of the Defias leadership. Wiley in Lakeshire offered a possible lead."},[132]={["opening"]="Wiley’s warning concerned a wider conspiracy: the Defias were, as he last heard, working with gnolls, kobolds and goblins.",["atomIDs"]={"132:description:53-91","132:description:94-185"},["sourceHash"]="a4d6117477875fad140f6b8e0ff247e16ba77a801e21fa507d5f13ba22ef4951",["review"]="SOURCE_BOUND_EDITORIAL_PARAPHRASE",["baseOverrideRevision"]=1,["baseOverrideSetup"]="Wiley’s information suggested that the Defias were preparing something larger. His note was meant for Stoutmantle."},[135]={["opening"]="Wiley’s mention of the Stonemasons troubled Gryan Stoutmantle. He hoped Mathias Shaw, head of SI:7, could explain their connection to the Defias.",["atomIDs"]={"135:description:1-60","135:description:63-96","135:description:99-150","135:description:153-214","135:description:216-295"},["sourceHash"]="e1ae7371fdbffac8dc595f8a3c9de1c50295dd117bbec6ffa630397de4390c99",["review"]="SOURCE_BOUND_EDITORIAL_PARAPHRASE",["baseOverrideRevision"]=1,["baseOverrideSetup"]="A mention of the Stonemasons raised a new question. Mathias Shaw in Stormwind might understand what it meant."},[141]={["opening"]="Shaw’s account named Edwin VanCleef as the leader of the Stonemasons’ Guild. His men had rebuilt Stormwind after the orcs razed it in the First War; apparently, their treatment afterward had left them dissatisfied.",["atomIDs"]={"141:description:1-61","141:description:64-154","141:description:157-273"},["sourceHash"]="9762b346dfae57e2ea3e640055fc2c1eacf19cc69e59a17f08b76ad22e59f4ab",["review"]="SOURCE_BOUND_EDITORIAL_PARAPHRASE",["baseOverrideRevision"]=1,["baseOverrideSetup"]="Shaw’s report connected the Stonemasons’ history to the rebuilding of Stormwind. It named Edwin VanCleef as their former leader."},[142]={["opening"]="The Defias hideout was still the missing piece. Stoutmantle’s scout had seen a messenger on the roads of Westfall, between Moonbrook, the Gold Coast Quarry and the Jangolode Mine.",["pending"]="Stoutmantle charged {actor} with intercepting the messenger and bringing back what he carried.",["result"]="{actor} brought the Defias messenger’s message to Stoutmantle.",["atomIDs"]={"142:description:1-55","142:description:58-193","142:description:196-221","142:description:224-284"},["sourceHash"]="0add70b5459a27ae0d76d402060e41dfb5731a824bd4f4a43a5336ce84b46b0f",["review"]="SOURCE_BOUND_EDITORIAL_PARAPHRASE",["baseOverrideRevision"]=1,["baseOverrideSetup"]="A messenger carried information about the Defias. Stoutmantle sought that message to establish where the investigation should lead."},[155]={["opening"]="A Defias turncoat offered a way to the gang’s hideout. The gang wanted him dead; in exchange for protection, he would guide his escort to VanCleef and his men.",["pending"]="{actor} took up the task of guarding the guide.",["result"]="{actor} escorted the traitor to the hideout and returned to Gryan Stoutmantle with the information.",["atomIDs"]={"155:description:148-205","155:description:245-278","155:description:281-328"},["sourceHash"]="6a857e62b6f36f4f150eb902dd3217fd4bf0e287daf57a7e3ef5ccfde3ffa21a",["review"]="SOURCE_BOUND_EDITORIAL_PARAPHRASE",["baseOverrideRevision"]=1,["baseOverrideSetup"]="A Defias defector offered to reveal the hideout in exchange for protection. The assignment called for an escort."},[166]={["opening"]="For Gryan Stoutmantle, VanCleef’s death had become necessary for the good of Westfall’s people, despite his misgivings about condemning a man to death.",["bridge"]="The search for the hideout had become a charge against VanCleef himself.",["bridgeFrom"]=155,["atomIDs"]={"166:description:50-85","166:description:88-247"},["sourceHash"]="5430c176684c5c728c9b0b0c6958ccf1f6e108b81f92bc9fb8b5a0df3f30ad87",["review"]="SOURCE_BOUND_EDITORIAL_PARAPHRASE",["baseOverrideRevision"]=1,["baseOverrideSetup"]="The investigation had reached its last charge: confront Edwin VanCleef and return proof to Stoutmantle."},[167]={["opening"]="Wilder Thistlenettle had escaped a collapsed mine beneath a barn in Moonbrook. His brother was among those who had not been heard from; an Explorers’ League badge might at least bring some peace of mind.",["atomIDs"]={"167:description:1-76","167:description:133-172","167:description:174-200","167:description:210-244","167:description:300-349","167:description:352-397","167:description:399-474"},["sourceHash"]="03aa326f35343f7ba1b58855193f07d52afa0c03160f3e3007012c5f17ba3e6e",["review"]="SOURCE_BOUND_EDITORIAL_PARAPHRASE"},[168]={["opening"]="The mine collapse had killed many of Wilder Thistlenettle’s friends. Their Miners’ Union Cards could identify them and give their families some resolution.",["atomIDs"]={"168:description:1-76","168:description:79-220","168:description:223-379"},["sourceHash"]="942252c67c66d0f4a11fce58984a9cbe4d47389f217a862122fca7662790440e",["review"]="SOURCE_BOUND_EDITORIAL_PARAPHRASE"},[456]={["opening"]="Heavy spring rains had upset Shadowglen’s balance. Nightsabers and thistle boars had flourished beyond what the forest could feed, while other beasts suffered.",["atomIDs"]={"456:description:47-125","456:description:130-251","456:description:256-329","456:description:332-387"},["sourceHash"]="e3aeee2bdb83486a5040f96f823fdf7afc9c32a5e85151134d59a12ad6a30ef4",["review"]="SOURCE_BOUND_EDITORIAL_PARAPHRASE"},[748]={["opening"]="Goblins and their servants had poisoned Mulgore’s sacred wells. Mull Thunderhorn needed paws and talons from the plains to make a cleansing totem for the Winterhoof well.",["atomIDs"]={"748:description:1-63","748:description:66-86","748:description:91-218","748:description:223-291","748:description:294-333","748:description:335-410","748:description:413-438","748:description:443-484"},["sourceHash"]="f4dee6e1ee072c9419d5596d79eaa24cf824a7fc3e6bbe90a7f4979596a4fb43",["review"]="SOURCE_BOUND_EDITORIAL_PARAPHRASE"},[754]={["opening"]="Mull Thunderhorn had finished the Winterhoof totem. Its power still had to be brought to the poisoned well, where goblins stood guard.",["pending"]="{actor} was to perform the cleansing ritual at the Winterhoof Water Well.",["result"]="{actor} performed the ritual at the Winterhoof Water Well and returned to Mull Thunderhorn.",["aftermath"]="Mull Thunderhorn reported that beasts were already drinking eagerly from the well.",["atomIDs"]={"754:description:1-62","754:description:65-129","754:description:132-190","754:description:195-283","754:description:288-306"},["sourceHash"]="e01d361a6e54cc9e3f8d04eec880efdcdd11be4ab9c8031203ea3f5349be3e8c",["review"]="SOURCE_BOUND_EDITORIAL_PARAPHRASE",["endingAtomIDs"]={"754:completion:1-99","754:completion:104-148","754:completion:150-203"}},[756]={["opening"]="The work turned to the Thunderhorn well. Claws from Mulgore’s prairie stalkers and flatland cougars were needed for its cleansing totem.",["atomIDs"]={"756:description:1-108","756:description:111-219","756:description:224-300"},["sourceHash"]="5e736c9f5e351b07156d243849f1d85b634e43c9158f29524b1e236d15763bd1",["review"]="SOURCE_BOUND_EDITORIAL_PARAPHRASE"},[758]={["opening"]="The Thunderhorn totem was ready. The next ritual lay at the well north of the village.",["pending"]="{actor} was to cleanse the Thunderhorn Water Well.",["result"]="{actor} carried out the cleansing ritual at the Thunderhorn Water Well.",["atomIDs"]={"758:description:1-23","758:description:26-87","758:description:92-202","758:description:205-236","758:description:241-266"},["sourceHash"]="45fd37bfdad0b11895e31dc037608627082da08034551e7dd540520d5a849564",["review"]="SOURCE_BOUND_EDITORIAL_PARAPHRASE"},[759]={["opening"]="Only the Wildmane well remained. The teeth of prairie wolf alphas were needed to prepare its cleansing totem; the predators wandered north, near the foot of Thunder Bluff.",["atomIDs"]={"759:description:1-75","759:description:78-178","759:description:181-255","759:description:260-329"},["sourceHash"]="edadd696e04b9e01d7ac8f1b6353d08c50767f49feab92a18f4985c65a684cf5",["review"]="SOURCE_BOUND_EDITORIAL_PARAPHRASE"},[760]={["opening"]="The Wildmane totem was made, and the last poisoned well lay north of Thunder Bluff. Mull Thunderhorn’s work had reached its final ritual.",["pending"]="{actor} was to bring the Wildmane totem to the well and perform the ritual.",["result"]="{actor} carried out the ritual at the Wildmane Water Well.",["aftermath"]="Mull Thunderhorn credited the cleansing of the wells with healing the land; Bloodhoof Village was grateful.",["atomIDs"]={"760:description:1-93","760:description:96-153","760:description:158-209","760:description:212-230","760:description:233-270","760:description:273-304"},["sourceHash"]="785c748c6b8f21237d76ea118fa1f3e316bcdac3c9cb8565a7f354b337630e5e",["review"]="SOURCE_BOUND_EDITORIAL_PARAPHRASE",["endingAtomIDs"]={"760:completion:1-15","760:completion:17-64","760:completion:66-99","760:completion:104-209"}},[954]={["opening"]="Demons filled the ruins of Bashal’Aran, feeding on the place’s lingering magic. Yet they avoided one shrine, where a strange blue aura shone on a western bluff.",["pending"]="{actor} took up the search for the aura’s source.",["result"]="{actor} found the source of the blue aura in Bashal’Aran.",["atomIDs"]={"954:description:1-70","954:description:72-224","954:description:229-307","954:description:309-394","954:description:396-450","954:description:455-489"},["sourceHash"]="5567879d8ba64e634932ed384e7a7bf9807db8ff50f25ebf546ad627fc48c0e3",["review"]="SOURCE_BOUND_EDITORIAL_PARAPHRASE",["baseOverrideRevision"]=1,["baseOverrideSetup"]="A strange blue aura lingered among Bashal’Aran’s ruins. The mystery began with a search for its source."},[955]={["opening"]="Asterion was a prisoner in spectral form, bound to the shrine by a magical seal. He hoped the grells’ earrings would carry a trace of the magic that held him.",["atomIDs"]={"955:description:1-103","955:description:105-218","955:description:223-259","955:description:261-400","955:description:402-501"},["sourceHash"]="1a0170ccbb423e2e56c02d1c03167080405737f1d7e03bdab81e2b9f1a7d4cc6",["review"]="SOURCE_BOUND_EDITORIAL_PARAPHRASE",["baseOverrideRevision"]=1,["baseOverrideSetup"]="Asterion described a long magical imprisonment. Grell earrings were sought as clues to what bound him."},[956]={["opening"]="Asterion suspected that the satyrs commanding the grells possessed the seal of his prison. Recovering the Ancient Moonstone Seal offered a chance to break his confinement.",["atomIDs"]={"956:description:1-114","956:description:116-190","956:description:195-237","956:description:239-278","956:description:280-395"},["sourceHash"]="bd5265c78a8d6a94de647f8520ac62ed0d966fd3ea90a511ca1e08f151088c13",["review"]="SOURCE_BOUND_EDITORIAL_PARAPHRASE",["baseOverrideRevision"]=1,["baseOverrideSetup"]="Asterion suspected that the satyrs held the seal binding him. The task called for the Ancient Moonstone Seal."},[957]={["opening"]="A Highborne’s craft had made Asterion’s prison. In the twin ruins of Ameth’Aran, an ancient blue flame offered a means of destroying the seal.",["pending"]="{actor} was to destroy the seal in the ancient flame.",["result"]="{actor} destroyed the Ancient Moonstone Seal in the flame at Ameth’Aran and returned to Asterion.",["aftermath"]="Asterion declared himself free. He remembered a world in which the Well of Eternity still stood and the Highborne held court with Azshara.",["atomIDs"]={"957:description:1-106","957:description:108-221","957:description:223-265","957:description:270-296"},["sourceHash"]="c762bbd20452d4836b2705736e8a17ae2f8a7ceca131b94fbe60628591c954c8",["review"]="SOURCE_BOUND_EDITORIAL_PARAPHRASE",["endingAtomIDs"]={"957:completion:1-15","957:completion:17-89","957:completion:91-124","957:completion:126-248","957:completion:253-318","957:completion:320-396"},["baseOverrideRevision"]=1,["baseOverrideSetup"]="A flame in Ameth’Aran offered a way to break the Ancient Moonstone Seal and release Asterion."},[2118]={["opening"]="Sickness gripped Darkshore’s thistle bears, turning them rabid and frenzied. Tharnariun Treetender hoped to find a cure and needed a living bear brought back in his trap.",["pending"]="{actor} was to capture a living Rabid Thistle Bear for Tharnariun.",["result"]="{actor} brought a living Rabid Thistle Bear back to Tharnariun.",["atomIDs"]={"2118:description:1-89","2118:description:94-152","2118:description:154-233","2118:description:235-269","2118:description:274-327","2118:description:329-411","2118:description:413-457","2118:description:459-480"},["sourceHash"]="2a5b1103abe6c706fc6de5e4fc33d7b5e7c03febb0a51d38e8627e6310412e0e",["review"]="SOURCE_BOUND_EDITORIAL_PARAPHRASE"},[2138]={["opening"]="Tharnariun’s cure had failed. He reluctantly called for the infected bears to be put down, hoping to limit the damage to Darkshore for a time; their deaths would not end the plague.",["pending"]="{actor} was charged with confronting twenty Rabid Thistle Bears.",["result"]="{actor} carried out Tharnariun’s charge against twenty Rabid Thistle Bears.",["atomIDs"]={"2138:description:1-40","2138:description:45-168","2138:description:173-232","2138:description:234-391"},["sourceHash"]="ef0d5a2e37446aa5733ab4cfa1c44893dd0b8335df4c12b83d37bf48ed9d6f3a",["review"]="SOURCE_BOUND_EDITORIAL_PARAPHRASE"},[2139]={["opening"]="The respite for Darkshore was brief. Tharnariun’s last request concerned the Den Mother, dwelling in a cave northeast near Bashal’Aran.",["pending"]="{actor} was to find and confront the Den Mother.",["result"]="{actor} carried out the charge against the Den Mother.",["atomIDs"]={"2139:description:1-68","2139:description:73-155","2139:description:157-260","2139:description:265-338","2139:description:340-405","2139:description:410-478","2139:description:480-488"},["sourceHash"]="144f6837f3c483d095483736e6b6e2e9046105e0c02b71b0da5bbf956556ae88",["review"]="SOURCE_BOUND_EDITORIAL_PARAPHRASE"}}
